/**
 * Calculate late fee for an invoice as of a given date.
 * @param {{ dueDate: string, ...invoice }} invoice - invoice object
 * @param {string} asOf - date in YYYY-MM-DD format
 * @returns {number} - late fee in cents (0 if not overdue)
 */
export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);

  return roundCents(due * daysOverdue * 0.0004);
}

/**
 * Get a dashboard summary of invoices and accounts receivable.
 * @param {Array} invoices - array of invoice objects
 * @param {string} asOf - date in YYYY-MM-DD format
 * @returns {{ counts: object, outstanding: number, overdue: object, topCustomers: Array }}
 */
export function dashboard(invoices, asOf) {
  const counts = {
    draft: invoices.filter((inv) => inv.status === 'draft').length,
    issued: invoices.filter((inv) => inv.status === 'issued').length,
    partially_paid: invoices.filter((inv) => inv.status === 'partially_paid').length,
    paid: invoices.filter((inv) => inv.status === 'paid').length,
  };

  const outstanding = invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .reduce((sum, inv) => sum + balanceDue(inv), 0);

  const overdueList = overdueInvoices(invoices, asOf);
  const overdue = {
    count: overdueList.length,
    amount: overdueList.reduce((sum, inv) => sum + inv.due, 0),
  };

  const customerDue = {};
  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .forEach((inv) => {
      const due = balanceDue(inv);
      if (!customerDue[inv.customerId]) {
        customerDue[inv.customerId] = 0;
      }
      customerDue[inv.customerId] += due;
    });

  const topCustomers = Object.entries(customerDue)
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding,
    overdue,
    topCustomers,
  };
}

